Lemma wins_hi_so : forall l h D n a b, aceil <= l -> aapp D n -> D <= a -> b <= D + n -> wins_hi [(l, h); (a, b)].
Proof.
  intros l h D n a b Hl AP Ha Hb. pose proof aceil_facts as (AF & _).
  constructor; [right; cbn; unfold AHI_LO; lia|].
  constructor; [| constructor]. destruct AP as [[P1 P2]|[P1 P2]]; cbn; [left; lia| right; lia].
Qed.
