Definition pd_frame (j8 : list byte) (s3 s2 s1 s0 ra : word) : list cell := [CB 8 j8; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra].

Definition apd_seg1_post (sp gp tp a3 a4 a5 a6 a7 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (t0 t1 t2 t3 t4 t5 t6 ra s0 s1 s2 s3 : word) (P lo : Z) (c : pcore) (pad7 pad2 : list byte) (m : mem) : machine_state -> Prop :=
  fun ms' => exists a2v m' j8,
    ms' = MS (mkR (wz APD_RA1) (wz (bv_unsigned sp + -48)) gp tp t0 t1 t2 (wz P) (wz (P + 80)) (wz (P + 168)) (wz (P + 176)) a2v
                  a3 a4 a5 a6 a7 (wz ASHADOW_BASE) (wz (Z.shiftr P 3 + ASHADOW_BASE)) s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (wz P_B_MBUF_DESTROY) fc None m' (seg_rom bsegs)
    /\ munch [(bv_unsigned sp + -48, bv_unsigned sp); (P, P + 8)]%Z m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo (bv_unsigned sp + -48)
    /\ rw_cells bsegs m' (bv_unsigned sp + -48) (pd_frame j8 s3 s2 s1 s0 ra)
    /\ rw_cells bsegs m' P (ParserCoreCells c pad7 pad2)
    /\ rw_cells bsegs m' (P + 288) [C8 (wz 0)] /\ rw_cells bsegs m' (P + 336) [C8 (wz 0)].
